// Package data holds the word data shared by the Go and JavaScript libraries:
// the official BIP39 English wordlist (english.txt) and the Seed Poet word
// categories and rhyme groups (seedpoet.json, generated by scripts/).
package data

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"strings"
)

//go:embed english.txt
var englishTxt string

//go:embed seedpoet.json
var seedpoetJSON []byte

// RhymeGroup is a set of BIP39 nouns that rhyme, under a phonetic key.
type RhymeGroup struct {
	Key   string
	Words []string
}

var (
	// BIP39 is the official BIP39 English wordlist, in order (2048 words).
	BIP39 []string
	// Verbs, Adjectives and Nouns are the words allowed at line positions 1, 2 and 3.
	Verbs, Adjectives, Nouns []string
	// Rhymes are the rhyme groups, sorted by key.
	Rhymes []RhymeGroup
)

func init() {
	BIP39 = strings.Fields(englishTxt)
	if len(BIP39) != 2048 {
		panic(fmt.Sprintf("data: english.txt has %d words, want 2048", len(BIP39)))
	}
	var raw struct {
		Format     int                 `json:"format"`
		Verbs      []string            `json:"verbs"`
		Adjectives []string            `json:"adjectives"`
		Nouns      []string            `json:"nouns"`
		Rhymes     [][]json.RawMessage `json:"rhymes"`
	}
	if err := json.Unmarshal(seedpoetJSON, &raw); err != nil {
		panic("data: seedpoet.json: " + err.Error())
	}
	if raw.Format != 1 {
		panic(fmt.Sprintf("data: unsupported seedpoet.json format %d", raw.Format))
	}
	Verbs, Adjectives, Nouns = raw.Verbs, raw.Adjectives, raw.Nouns
	for _, r := range raw.Rhymes {
		var g RhymeGroup
		if len(r) != 2 || json.Unmarshal(r[0], &g.Key) != nil || json.Unmarshal(r[1], &g.Words) != nil {
			panic("data: malformed rhyme group")
		}
		Rhymes = append(Rhymes, g)
	}

	known := make(map[string]bool, len(BIP39))
	for _, w := range BIP39 {
		known[w] = true
	}
	check := func(what string, words []string) {
		for _, w := range words {
			if !known[w] {
				panic(fmt.Sprintf("data: %s word %q is not in the BIP39 list", what, w))
			}
		}
	}
	check("verb", Verbs)
	check("adjective", Adjectives)
	check("noun", Nouns)
	for _, g := range Rhymes {
		check("rhyme", g.Words)
	}
}
